# frozen_string_literal: true

# LLM Provider Manager — generated by extendable-rails.
#
# Delegates to the gem's ProviderManager which handles the fallback chain.
# The provider chain is configured in config/initializers/mcp.rb via
# ExtendableRails.configure.
#
# Usage:
#   response = Mcp::Llm::ProviderManager.chat(
#     messages: [{ role: "user", content: "Hello!" }]
#   )
#
module Mcp
  module Llm
    class ProviderManager
      class << self
        def chat(messages:, **options)
          ExtendableRails::Mcp::Llm::ProviderManager.chat(
            messages: messages, **options
          )
        end
      end
    end
  end
end
